  KEY `users_companyId_roleId_idx` (`companyId`,`roleId`),
  KEY `users_managerId_idx` (`managerId`),
  KEY `users_departmentId_fkey` (`departmentId`),
  KEY `users_positionId_fkey` (`positionId`),
  CONSTRAINT `users_companyId_fkey` FOREIGN KEY (`companyId`) REFERENCES `companies` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `users_roleId_fkey` FOREIGN KEY (`roleId`) REFERENCES `roles` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `users_departmentId_fkey` FOREIGN KEY (`departmentId`) REFERENCES `departments` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `users_positionId_fkey` FOREIGN KEY (`positionId`) REFERENCES `job_positions` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `users_managerId_fkey` FOREIGN KEY (`managerId`) REFERENCES `users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
